# name: palindrome_choice_rate
# description: Among trials where exactly one sequence is a palindrome (mirror-symmetric, e.g. HTTTTTTH, HHHTTHHH), the proportion choosing the palindrome; observed below the null means people penalise visible symmetry beyond what the model's alternation/balance/streak terms predict, above means they favour it.
def test_statistic(df):
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: (s == s[::-1]) for s in u}
    a = df["sequence_a"].map(m).astype(bool).to_numpy()
    b = df["sequence_b"].map(m).astype(bool).to_numpy()
    sel = a ^ b
    if sel.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    chose = np.where(a, c, 1 - c)
    return float(chose[sel].mean())

# name: longer_initial_run_choice_rate
# description: Among trials whose sequences begin with runs of different length, the proportion choosing the sequence with the LONGER initial run; observed below the null means people penalise an opening streak (primacy) more than the model, which weighs the final run but not the first, predicts.
def test_statistic(df):
    def first_run(s):
        k = 1
        while k < len(s) and s[k] == s[0]:
            k += 1
        return k / len(s)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: first_run(s) for s in u}
    fa = df["sequence_a"].map(m).to_numpy(dtype=float)
    fb = df["sequence_b"].map(m).to_numpy(dtype=float)
    sel = fa != fb
    if sel.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    chose = np.where(fa > fb, c, 1 - c)
    return float(chose[sel].mean())

# name: constant_sequence_choice_rate
# description: Among trials where exactly one sequence is a single repeated outcome (all H or all T), the proportion choosing that constant sequence; observed above the null means people choose the all-same sequence more often than the model predicts (e.g. it over-penalises it against other degenerate sequences), below means less often.
def test_statistic(df):
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: len(set(s)) == 1 for s in u}
    a = df["sequence_a"].map(m).astype(bool).to_numpy()
    b = df["sequence_b"].map(m).astype(bool).to_numpy()
    sel = a ^ b
    if sel.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    chose = np.where(a, c, 1 - c)
    return float(chose[sel].mean())

# name: perfect_alternation_choice_rate
# description: Among trials where exactly one sequence strictly alternates (HTHT.../THTH...), the proportion choosing that sequence; observed above the null means people favour perfect alternation more than the quadratic ideal-switch-rate term predicts, below means they reject it as too regular more than predicted.
def test_statistic(df):
    def alt(s):
        return all(x != y for x, y in zip(s, s[1:]))
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: alt(s) for s in u}
    a = df["sequence_a"].map(m).astype(bool).to_numpy()
    b = df["sequence_b"].map(m).astype(bool).to_numpy()
    sel = a ^ b
    if sel.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    chose = np.where(a, c, 1 - c)
    return float(chose[sel].mean())

# name: participant_left_rate_sd
# description: Standard deviation across participants of their proportion of Left responses; observed above the null means individuals have personal side (position) biases that the model, which has no left/right bias term, under-produces.
def test_statistic(df):
    r = df.groupby("participant_id")["chose_left"].mean()
    return float(r.std(ddof=1))

# name: periodic_pattern_choice_rate
# description: Among trials where exactly one sequence is built by repeating a non-constant chunk of length 2-4 (e.g. HTTHTTHT, HHTTHHTT, HTHHTHHT; strict alternation excluded), the proportion choosing the periodic sequence; observed below the null means people detect and penalise repeated chunks beyond what the model's alternation/streak terms predict.
def test_statistic(df):
    def periodic(s):
        n = len(s)
        if len(set(s)) == 1 or all(x != y for x, y in zip(s, s[1:])):
            return False
        for p in (2, 3, 4):
            if n >= 2 * p and all(s[i] == s[i - p] for i in range(p, n)):
                return True
        return False
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: periodic(s) for s in u}
    a = df["sequence_a"].map(m).astype(bool).to_numpy()
    b = df["sequence_b"].map(m).astype(bool).to_numpy()
    sel = a ^ b
    if sel.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    chose = np.where(a, c, 1 - c)
    return float(chose[sel].mean())
